CREATE TABLE api_credentials(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,key_id TEXT NOT NULL,subject_id TEXT NOT NULL,subject_kind TEXT NOT NULL CHECK(subject_kind IN ('human','service_account','workload')),revocation_epoch BIGINT NOT NULL CHECK(revocation_epoch>=0),expires_at_ms BIGINT NOT NULL,disabled BOOLEAN NOT NULL,password_hash TEXT NOT NULL CHECK(octet_length(password_hash)<=256),created_by TEXT NOT NULL,operation_id TEXT NOT NULL,request_digest TEXT NOT NULL CHECK(length(request_digest)=64),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,key_id),UNIQUE(organization_id,tenant_id,project_id,agent_uid,created_by,operation_id),FOREIGN KEY(organization_id,tenant_id,subject_id) REFERENCES principals(organization_id,tenant_id,subject_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE credential_revocations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,key_id TEXT NOT NULL,operation_id TEXT NOT NULL,actor_id TEXT NOT NULL,result_json TEXT NOT NULL CHECK(octet_length(result_json)<=4096),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,operation_id));
ALTER TABLE api_credentials ENABLE ROW LEVEL SECURITY;
ALTER TABLE api_credentials FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON api_credentials USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
ALTER TABLE credential_revocations ENABLE ROW LEVEL SECURITY;
ALTER TABLE credential_revocations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON credential_revocations USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
CREATE FUNCTION protect_api_credential() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable credential'; END IF; IF (to_jsonb(OLD)-'disabled')<>(to_jsonb(NEW)-'disabled') OR (OLD.disabled AND NOT NEW.disabled) THEN RAISE EXCEPTION 'immutable credential'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_api_credential BEFORE UPDATE OR DELETE ON api_credentials FOR EACH ROW EXECUTE FUNCTION protect_api_credential();
CREATE TRIGGER immutable_credential_revocation BEFORE UPDATE OR DELETE ON credential_revocations FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
